"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([["918629"],{949941:function(e){e.exports=JSON.parse('{"tag":{"label":"reComputer","permalink":"/tags/re-computer","allTagsPath":"/tags","count":8,"items":[{"id":"es/Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics/es_reComputer_Robotics_Getting_Started","title":"Comenzando con reComputer Robotics","description":"El reComputer Robotics J401 es una placa portadora de IA de borde de alto rendimiento dise\xf1ada para aplicaciones rob\xf3ticas avanzadas. Soporta m\xf3dulos NVIDIA Jetson Orin Nano y Orin NX en modo Super/MAXN, entregando hasta 157 TOPS de potencia de c\xf3mputo de IA. La placa ofrece amplias opciones de conectividad, incluyendo Ethernet Gigabit dual, m\xfaltiples puertos USB 3.2, CAN, ranuras M.2 para m\xf3dulos 5G/Wi-Fi/BT, y soporte opcional para c\xe1maras GMSL2. Pre-instalado con JetPack 6, asegura un despliegue sin problemas para el desarrollo rob\xf3tico. El dise\xf1o robusto soporta amplias temperaturas de operaci\xf3n e incluye un disipador de calor pre-instalado con ventilador. La configuraci\xf3n involucra flashear el SO JetPack en un SSD NVMe usando una PC host Ubuntu compatible, seguido de configuraci\xf3n de hardware y uso de interfaces. Se proporcionan especificaciones detalladas de hardware, dibujos mec\xe1nicos y recursos t\xe9cnicos para desarrolladores, junto con canales de soporte comunitario y t\xe9cnico para resoluci\xf3n de problemas y discusi\xf3n.","permalink":"/es/recomputer_robotics_j401_getting_started"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics/reComputer_Robotics_Getting_Started","title":"Getting Started with reComputer Robotics","description":"The reComputer Robotics J401 is a high-performance edge AI carrier board designed for advanced robotics applications. It supports NVIDIA Jetson Orin Nano and Orin NX modules in Super/MAXN mode, delivering up to 157 TOPS of AI computing power. The board offers extensive connectivity options, including dual Gigabit Ethernet, multiple USB 3.2 ports, CAN, M.2 slots for 5G/Wi-Fi/BT modules, and optional GMSL2 camera support. Pre-installed with JetPack 6, it ensures seamless deployment for robotics development. The rugged design supports wide operating temperatures and includes a pre-installed heatsink with fan. The setup involves flashing the JetPack OS onto an NVMe SSD using a compatible Ubuntu host PC, followed by hardware configuration and interface usage. Detailed hardware specifications, mechanical drawings, and technical resources are provided for developers, along with community and technical support channels for troubleshooting and discussion.","permalink":"/recomputer_robotics_j401_getting_started"},{"id":"es/Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics/es_reComputer_Robotics_Hardware_Interfaces_Usage","title":"Hardware y Uso de Interfaces de reComputer Robotics","description":"Esta wiki proporciona una introducci\xf3n completa a las caracter\xedsticas de hardware y el uso de interfaces de la placa portadora reComputer Jetson Robotics J401. Cubre especificaciones detalladas, m\xf3dulos compatibles, instrucciones de configuraci\xf3n y gu\xedas pr\xe1cticas para usar varias interfaces como M.2, Ethernet, USB, CAN, UART, I2C y expansi\xf3n de c\xe1mara GMSL2, ayudando a los usuarios a comenzar r\xe1pidamente con el desarrollo de rob\xf3tica en la plataforma J401.","permalink":"/es/recomputer_robotics_j401_hardware_interfaces_usage"},{"id":"es/Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Mini/es_reComputer_Mini_Hardware_Interfaces_Usage","title":"Hardware y Uso de Interfaces del reComputer Mini","description":"Este art\xedculo cubre el hardware y las interfaces de la serie reComputer Mini J40, incluyendo alimentaci\xf3n, pantalla, ranuras M.2 para Wi-Fi y SSD, puertos USB, RTC, gesti\xf3n del ventilador, y m\xe1s. Proporciona instrucciones de configuraci\xf3n y consejos de pruebas de rendimiento para ayudar a los usuarios a expandir sus proyectos.","permalink":"/es/recomputer_jetson_mini_hardware_interfaces_usage"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Mini/reComputer_Mini_Hardware_Interfaces_Usage","title":"reComputer Mini Hardware and Interfaces Usage","description":"This article covers the hardware and interfaces of the reComputer Mini J40 series, including power, display, M.2 slots for Wi-Fi and SSD, USB ports, RTC, fan management, and so on. It provides setup instructions and performance testing tips to help users expand their projects.","permalink":"/recomputer_jetson_mini_hardware_interfaces_usage"},{"id":"ja/Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Mini/ja_reComputer_Mini_Hardware_Interfaces_Usage","title":"reComputer Mini \u30CF\u30FC\u30C9\u30A6\u30A7\u30A2\u3068\u30A4\u30F3\u30BF\u30FC\u30D5\u30A7\u30FC\u30B9\u306E\u4F7F\u7528\u65B9\u6CD5","description":"\u3053\u306E\u8A18\u4E8B\u3067\u306F\u3001reComputer Mini J40\u30B7\u30EA\u30FC\u30BA\u306E\u30CF\u30FC\u30C9\u30A6\u30A7\u30A2\u3068\u30A4\u30F3\u30BF\u30FC\u30D5\u30A7\u30FC\u30B9\u306B\u3064\u3044\u3066\u8AAC\u660E\u3057\u307E\u3059\u3002\u3053\u308C\u306B\u306F\u3001\u96FB\u6E90\u3001\u30C7\u30A3\u30B9\u30D7\u30EC\u30A4\u3001Wi-Fi\u304A\u3088\u3073SSD\u7528\u306EM.2\u30B9\u30ED\u30C3\u30C8\u3001USB\u30DD\u30FC\u30C8\u3001RTC\u3001\u30D5\u30A1\u30F3\u7BA1\u7406\u306A\u3069\u304C\u542B\u307E\u308C\u307E\u3059\u3002\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\u624B\u9806\u3084\u6027\u80FD\u30C6\u30B9\u30C8\u306E\u30D2\u30F3\u30C8\u3092\u63D0\u4F9B\u3057\u3001\u30E6\u30FC\u30B6\u30FC\u304C\u30D7\u30ED\u30B8\u30A7\u30AF\u30C8\u3092\u62E1\u5F35\u3059\u308B\u306E\u3092\u652F\u63F4\u3057\u307E\u3059\u3002","permalink":"/ja/recomputer_jetson_mini_hardware_interfaces_usage"},{"id":"zh-CN/Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Mini/cn_reComputer_Mini_Hardware_Interfaces_Usage","title":"reComputer Mini \u786C\u4EF6\u548C\u63A5\u53E3\u4F7F\u7528\u6307\u5357","description":"\u672C\u6587\u6DB5\u76D6\u4E86 reComputer Mini J40 \u7CFB\u5217\u7684\u786C\u4EF6\u548C\u63A5\u53E3\uFF0C\u5305\u62EC\u7535\u6E90\u3001\u663E\u793A\u3001\u7528\u4E8E Wi-Fi \u548C SSD \u7684 M.2 \u63D2\u69FD\u3001USB \u63A5\u53E3\u3001RTC\u3001\u98CE\u6247\u7BA1\u7406\u7B49\u5185\u5BB9\u3002\u63D0\u4F9B\u8BBE\u7F6E\u8BF4\u660E\u548C\u6027\u80FD\u6D4B\u8BD5\u6280\u5DE7\uFF0C\u5E2E\u52A9\u7528\u6237\u6269\u5C55\u9879\u76EE\u3002","permalink":"/cn/recomputer_jetson_mini_hardware_interfaces_usage"},{"id":"Edge/NVIDIA_Jetson/reComputer_Jetson_Series/reComputer_Robotics/reComputer_Robotics_Hardware_Interfaces_Usage","title":"reComputer Robotics Hardware and Interfaces Usage","description":"This wiki provides a comprehensive introduction to the hardware features and interface usage of the reComputer Jetson Robotics J401 carrier board. It covers detailed specifications, supported modules, setup instructions, and practical guides for using various interfaces such as M.2, Ethernet, USB, CAN, UART, I2C, and GMSL2 camera expansion, helping users quickly get started with robotics development on the J401 platform.","permalink":"/recomputer_robotics_j401_hardware_interfaces_usage"}],"unlisted":false}}')}}]);